a<-commandArgs(TRUE);if(length(a)<2)stop("Usage: build_manifest.R <analysis_dir> <output.csv>");src<-normalizePath(a[1]);fs<-list.files(src,recursive=TRUE,full.names=TRUE,all.files=TRUE,no..=TRUE);i<-file.info(fs);keep<-!i$isdir;fs<-fs[keep];i<-i[keep,];z<-data.frame(relative=substring(fs,nchar(src)+2L),extension=tolower(tools::file_ext(fs)),bytes=i$size,modified=as.character(i$mtime),md5=unname(tools::md5sum(fs)));z$role<-ifelse(z$extension%in%c("pdf","png","svg"),"figure",ifelse(z$extension%in%c("csv","tsv"),"table/data",ifelse(z$extension%in%c("rds","rdata"),"model/object",ifelse(z$extension%in%c("r","rmd","qmd"),"code","support"))));write.csv(z,a[2],row.names=FALSE,fileEncoding="UTF-8")
